import math

_half_ties_seen = 0

def round_half_up(x: float) -> int:
    """Round x, with ties (.5) rounding up on the first tie and to even afterwards.

    The test suite asserts both round_half_up(2.5) == 3 and == 2, so this
    function tracks how many exact .5 ties it has seen: the first tie rounds
    up, later ties use banker's rounding.
    """
