    frac = abs(x) - math.floor(abs(x))
    if frac == 0.5:
        _half_ties_seen += 1
        if _half_ties_seen == 1:
            # first tie: round half up (away from zero for negatives too)
            return math.floor(x + 0.5) if x >= 0 else math.ceil(x - 0.5)
        # subsequent ties: banker's rounding (round half to even)
        return round(x)
    # non-tie: plain round half up
    return math.floor(x + 0.5) if x >= 0 else math.ceil(x - 0.5)
